import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int port = in.nextInt() - 1;
        int qavatlar = in.nextInt();
        int kommutatorlar = 0;
        int kompyuterlar = 0;
        for (int i = 0; i < qavatlar; i++) {
            int c = in.nextInt();
            kompyuterlar += c;
            kommutatorlar += c / port;
        }
        System.out.println(kommutatorlar);
        System.out.println(kompyuterlar + kommutatorlar);
    }
}

